TP.register({id:"lp2-g4",lp:2,grade:"4",mode:"curriculum",checks:1,nextGrade:"5th grade",build(E){const F=E.F;const STORY="Saturday was the last picking day at Hillcrest Orchard. Mina and her cousin Theo had one job. They had to fill the big wooden bin before the cider press started at three o’clock. The bin was titanic. Mina could have curled up inside it with room to spare. “We will never fill that,” Theo said. He kicked a fallen apple down the row. “We will if we stop talking,” said Mina. She climbed the ladder and passed apples down two at a time. Theo set each one in the bin as gently as an egg, because bruised apples spoil quickly. For a while the work went smoothly. Then Mina reached for a far branch, and the ladder wobbled. Her stomach dropped to her shoes. Theo grabbed the legs of the ladder and held on tight. “Thanks,” Mina said in a small voice. After that, she moved the ladder instead of stretching. At ten minutes to three, Theo set the last apple on top of the pile. His shirt was sticky, and his arms ached. Still, he was smiling. “Next year,” he said, “let’s ask for two bins.”";const STORY_N=STORY.split(/\s+/).length;const TEXT_A={title:"Why Apples Need Bees",body:"An apple starts as a blossom. In spring, each blossom holds a yellow dust called pollen. Before a blossom can turn into an apple, pollen from a different kind of apple tree must reach it. Honeybees do most of this work. As a bee drinks nectar, pollen sticks to its fuzzy body. At the next tree, some of that pollen rubs off. A blossom that gets plenty of pollen grows into a round, full apple. A blossom that gets none dries up and falls off."};const TEXT_B={title:"Hives for Hire",body:"Many apple growers do not keep bees all year. Instead, they rent hives from beekeepers. Trucks bring the hives at night, when the bees are resting inside. A grower may set out one or two hives for every acre of trees. The timing has to be right, because apple blossoms stay open for only about ten days. Weather matters too. Honeybees stay in the hive when it is rainy, windy, or colder than about 55 degrees. When the blossoms fade, the hives are trucked to another farm."};const WORDS=["unbreakable","disagreement","preheated","carefully","misplaced","invisible","transportation","nonfiction","autograph","thermometer","unhelpful","discovery","retrindable","misfloction"];const FONT=`font-family="Andika,sans-serif" font-weight="700"`;function twoTextsHtml(){return`<div class="texts"><article><h3>Text 1: ${TEXT_A.title}</h3><p>${TEXT_A.body}</p></article><article><h3>Text 2: ${TEXT_B.title}</h3><p>${TEXT_B.body}</p></article></div>`}function lookBackTexts(){return`<details class="look-back" data-again="1" open><summary>Look back at the two texts</summary>${twoTextsHtml()}</details>`}function lookBackStory(){return`<details class="look-back" data-again="1" open><summary>Look back at the story</summary><p class="passage sm">${STORY}</p></details>`}function foldRepeats(view){if(view&&view.querySelectorAll)view.querySelectorAll("details[data-again]").forEach(d=>{d.open=false})}function sign(big,small){return`<svg viewBox="0 0 460 190" width="460" role="img" aria-label="Farm stand sign that says ${big} ${small}"><rect x="70" y="150" width="16" height="40" fill="var(--gold-ink)"/><rect x="374" y="150" width="16" height="40" fill="var(--gold-ink)"/><rect x="8" y="8" width="444" height="146" rx="16" fill="var(--surface)" stroke="var(--gold-ink)" stroke-width="6"/><text x="230" y="84" font-size="64" ${FONT} fill="var(--ink)" text-anchor="middle">${big}</text><text x="230" y="130" font-size="28" ${FONT} fill="var(--sea)" text-anchor="middle">${small}</text></svg>`}function fracRect(parts,shade){const w=320,h=96;let s=`<svg viewBox="0 0 ${w+8} ${h+8}" width="${w+8}" role="img" aria-label="Bar cut into ${parts} equal parts with ${shade} shaded">`;for(let k=0;k<parts;k++)s+=`<rect x="${4+k*w/parts}" y="4" width="${w/parts}" height="${h}" fill="${k<shade?"var(--gold)":"var(--surface)"}" stroke="var(--ink)" stroke-width="4"/>`;return s+"</svg>"}function roundLine(){const w=640,x0=50,x1=590,y=44;let s=`<svg viewBox="0 0 ${w} 110" width="${w}" role="img" aria-label="Number line from 3,000 to 4,000 with a mark at every hundred"><line x1="${x0}" y1="${y}" x2="${x1}" y2="${y}" stroke="var(--ink)" stroke-width="4"/>`;for(let k=0;k<=10;k++){const x=x0+(x1-x0)*k/10,bigTick=k===0||k===5||k===10;s+=`<line x1="${x}" y1="${y-(bigTick?20:12)}" x2="${x}" y2="${y+(bigTick?20:12)}" stroke="var(--ink)" stroke-width="4"/>`;if(bigTick)s+=`<text x="${x}" y="${y+54}" font-size="26" ${FONT} fill="var(--ink)" text-anchor="middle">${k===0?"3,000":k===5?"3,500":"4,000"}</text>`}return s+"</svg>"}function jugs(){function jug(x,w,h,name){const top=150-h;return`<rect x="${x+w/2-12}" y="${top-22}" width="24" height="24" fill="var(--surface)" stroke="var(--ink)" stroke-width="4"/><rect x="${x}" y="${top}" width="${w}" height="${h}" rx="12" fill="var(--surface)" stroke="var(--ink)" stroke-width="4"/><rect x="${x+4}" y="${top+h/2}" width="${w-8}" height="${h/2-4}" rx="8" fill="var(--gold)"/><line x1="${x}" y1="${top+h/2}" x2="${x+w}" y2="${top+h/2}" stroke="var(--ink)" stroke-width="3" stroke-dasharray="6 5"/><text x="${x+w/2}" y="184" font-size="22" ${FONT} fill="var(--ink)" text-anchor="middle">${name}</text>`}return`<svg viewBox="0 0 420 195" width="420" role="img" aria-label="A small jug and a big jug. Each one is half full of cider.">${jug(60,70,70,"small jug")}${jug(230,130,124,"big jug")}</svg>`}const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const PRESS="Here is what happens at the press at Hillcrest. The apples ride up a belt and drop into a grinder, which chops them into a coarse mush called pomace. The pomace is wrapped in heavy cloth and stacked in layers on a rack. A flat plate comes down on the stack and squeezes it harder and harder, and juice runs out of the sides and into a tank below. One ton of apples makes about one hundred twenty gallons of cider.";const STOPS=[{id:1,title:"Apple Word Pick",short:"Word Pick",parts:[{std:["RF.4.3"],kind:"words",words:WORDS,n:14,dur:110,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading long words with prefixes, roots, and suffixes",key:["Read each word. Count a word as correct when the student reads it right on the first try or fixes it without help.","The last two are made-up words. Listen for the chunks: re-trind-a-ble and mis-floc-tion.","Watch for: prefixes (un-, dis-, pre-, mis-, in-, non-, trans-), roots (port, graph, therm, meter, vis), suffixes (-able, -ment, -ful, -ly, -ible, -tion, -y), and whether the student breaks long words into syllables or guesses from the first letters."]}]},{id:2,title:"Count the Crop",short:"Crop Count",parts:[{std:["4.NBT.A.1"],dur:160,dir:"Look at the sign. Answer out loud and tell how you know.",desc:"place value and how a digit is worth 10 times as much one place to the left",fig:()=>`<div class="figure">${sign("5,550","apples picked today")}</div>`,qs:["The number on the sign has three 5s. What is each 5 worth?","Compare the 5 in the thousands place to the 5 in the hundreds place. How many times as much is it worth? How do you know?","A crate holds 40 apples. A bin holds 10 times as many. How many apples does a bin hold? What happens to the 4?","True or false and why: 6,000 ÷ 600 = 10","Spot the mistake: A picker says, “In 9,090 the first 9 is worth 10 times as much as the second 9.” Explain how you know that is wrong."],key:["5,000 and 500 and 50. Partial: two of the three values given is approaching.","10 times as much. 5,000 is 10 times 500, because each place is worth 10 times the place to its right. Partial: naming 10 with no reason from the places is approaching.","400 apples. The 4 moves one place to the left, from the tens place to the hundreds place. Partial: 400 right with nothing said about the 4 moving a place is approaching.","True. 6,000 is 10 times as much as 600. The 6 is one place to the left. Partial: saying true with no reason is approaching.","The first 9 is 9,000 and the second 9 is 90. The 9s are two places apart, so the first 9 is worth 100 times as much (10 times 10). Partial: naming the two values with no account of their being two places apart is approaching."]}]},{id:3,title:"Read Under the Apple Tree",short:"Read",parts:[{std:["RF.4.4"],kind:"read",n:STORY_N,label:"words read correctly",dur:90,dir:"Read the story out loud. Use your best reading voice.",desc:`a ${STORY_N}-word grade-level story read aloud`,html:()=>`<p class="passage">${STORY}</p>`,key:[`${STORY_N} words. Time 1 minute and mark errors and self-corrections on your own copy.`,"Fall grade 4 benchmark: about 94 words correct per minute (50th percentile).","Note pace and expression, such as a change of voice for what Mina and Theo say."]}]},{id:4,title:"The Last Bin",short:"Story Qs",parts:[{title:"Prove It",std:["RL.4.1"],dur:105,dir:"Answer out loud. Look back at the story and point to the details that prove your answer.",desc:"questions answered with details and examples from a story",html:()=>`<p class="passage sm">${STORY}</p>`,after:foldRepeats,qs:["Why did Theo set each apple down so gently? Find the detail in the story.","How did Theo feel about the job at the start? Which details show it?","What did Mina learn when the ladder wobbled? Which detail shows it?"],key:["So the apples would not get bruised. Detail: bruised apples spoil quickly. (explicit)","He thought the job was too big and felt grumpy or discouraged. Details: he said they would never fill the bin, and he kicked a fallen apple down the row. (inference)","Reaching too far is not safe. Detail: after that, she moved the ladder instead of stretching. Also accept: her stomach dropped, and she thanked Theo in a small voice. (inference)"]},{title:"Word Detective",std:["RL.4.4"],dur:70,dir:"Look back at the story. Answer out loud.",desc:"meanings of words and phrases in a story, including one from mythology",html:()=>lookBackStory(),qs:["The story says the bin was “titanic.” What does titanic mean here? Which words in the story help you? Bonus: titanic comes from the Titans in Greek myths. What do you think the Titans were like?","What does “Her stomach dropped to her shoes” mean?","Theo set each apple down “as gently as an egg.” What does that tell you?"],key:["Huge. Clue: Mina could have curled up inside it with room to spare. The Titans were giant, powerful beings in Greek myths. Tell the student if they do not know. (allusion to mythology)","She felt a sudden rush of fear when the ladder moved.","He was very careful, the way you would be with an egg that could break."]}]},{id:5,title:"Round Up the Baskets",short:"Rounding",parts:[{std:["4.NBT.A.3"],dur:160,dir:"Say 1 to 4 out loud. For number 5, explain how you know.",desc:"rounding multi-digit numbers to a given place",fig:()=>`<div class="figure">${sign("46,382","apples picked this fall")}</div>`,qs:["Round the number on the sign to the nearest ten.","Round the number on the sign to the nearest thousand.","Round the number on the sign to the nearest ten thousand.","Estimate first: 7,952 people came to the orchard. Round to the nearest hundred.","Spot the mistake: Kai rounded 3,482 to the nearest thousand and got 4,000. Use the number line. Is Kai right? Explain how you know."],fig2:()=>`<div class="figure">${roundLine()}</div>`,key:["46,380. Partial: 46,370 rounds down when the ones digit is 5 or more and does not count.","46,000. Partial: 47,000 rounds up when the hundreds digit is below 5 and does not count.","50,000. Partial: 40,000 rounds down when the thousands digit is 6 and does not count.","8,000. Partial: 7,900 rounds down when the tens digit is 5 and does not count.","Kai is not right. 3,482 rounds to 3,000. It is less than the halfway mark of 3,500, so it is closer to 3,000. Also accept: the hundreds digit is 4, so round down. Partial: saying Kai is wrong with no reason from the halfway mark is approaching."]}]},{id:6,title:"Bee Business",short:"Two Texts",parts:[{title:"Use the Text",std:["RI.4.1"],dur:150,dir:"Read both texts to yourself. Then answer out loud. Tell which details helped you.",desc:"questions answered with details and examples from informational texts",html:()=>twoTextsHtml(),after:foldRepeats,qs:["How does pollen get from one apple tree to another? Give details from Text 1.","True or false: Every apple blossom turns into an apple. Prove it with a detail from Text 1.","Why do the trucks bring the hives at night? Use a detail from Text 2.","Do the rented hives stay in one orchard all summer? Which details in Text 2 help you know?"],key:["Pollen sticks to the fuzzy body of a bee while it drinks nectar. At the next tree, some of the pollen rubs off. (explicit)","False. A blossom that gets no pollen dries up and falls off. (explicit)","At night the bees are resting inside the hive, so they all get moved with it and are not left behind. (inference)","No. The blossoms are open only about ten days, and when they fade the hives go to another farm. (inference)"]},{title:"Put It Together",std:["RI.4.9"],n:3,dur:110,dir:"Think about both texts. Answer out loud.",desc:"putting together information from two texts on the same topic",html:()=>lookBackTexts(),qs:["Use both texts. Explain why a week of cold rain in spring could mean fewer apples in the fall.","A grower rents two hives for every acre. Text 2 calls that plenty of bees. But the grower plants only one kind of apple tree. Use both texts. Explain why that orchard would still grow very few apples."],key:["Uses Text 2: honeybees stay in the hive when it is rainy or colder than about 55 degrees, and the blossoms are open for only about ten days.","Connects to Text 1: blossoms that get no pollen dry up and fall off, so fewer blossoms become apples.","The hives give the orchard all the bees it needs, which is the Text 2 half. Text 1 is the other half: the pollen has to come from a different kind of apple tree, so in an orchard of one kind the bees would carry pollen only between trees of that same kind, the blossoms would get none of the pollen they need, and a blossom that gets none dries up and falls off. Needs the hive supply from Text 2 joined to the different-kind rule from Text 1. One text on its own does not answer it."]}]},{id:7,title:"Apple Pie Pieces",short:"Pie Pieces",parts:[{std:["4.NF.A.1"],dur:160,dir:"Look at the two bars. Answer out loud. Write numbers 2 and 3 on your paper and hold it up.",desc:"explaining and making equivalent fractions",fig:()=>`<div class="figure"><div>${fracRect(4,3)}<p class="fig-label">3/4</p></div><div>${fracRect(8,6)}<p class="fig-label">6/8</p></div></div>`,qs:["Do the two bars show the same amount? Explain. Talk about the number of pieces and the size of the pieces.","Fill in the missing number: 3/5 = ?/10","Write two fractions that are equal to 1/3.","True or false and why: 2/6 = 4/8","A pie is cut into 12 equal slices. The farm stand sells 9 slices. The baker says, “We sold 3/4 of the pie.” Is the baker right? Explain how you know."],key:["Yes. The second bar has 2 times as many pieces, and each piece is half as big, so the shaded amount is the same. Partial: saying yes with nothing said about the size of the pieces is approaching.","6 (3/5 = 6/10). Or: double the top and the bottom of 3/5 to get 6/10.","Any two: 2/6, 3/9, 4/12, 5/15. Partial: one equal fraction given is approaching.","False. 2/6 is the same as 4/12 or 1/3. 4/8 is the same as 1/2. The top was doubled but the bottom was not. Partial: saying false with no reason is approaching.","Yes. 9/12 = 3/4. Put the 12 slices in groups of 3: that makes 4 groups, and 3 of the groups were sold. Partial: saying yes with no grouping and no equivalence shown is approaching."]}]},{id:8,title:"Orchard Notebook",short:"Notebook",parts:[{std:["W.4.8"],dur:110,dir:"Look back at the two texts. Write your notes on your paper and hold it up.",desc:"taking notes in their own words, sorting the notes, and listing sources",html:()=>`<p class="big" style="margin-top:0">You are gathering facts for a report about bees and apple trees.</p>${lookBackTexts()}`,qs:["Write two notes, one from each text. Keep them short and use your own words.","Sort your notes. Write a heading above each note: What Bees Do or What Growers Do.","List your sources. Next to each note, write the title of the text it came from."],key:["Two short notes, one from each text, in the student’s own words and not copied sentences. Examples: bees carry pollen from tree to tree; growers rent hives for about ten days. (gathers information, takes notes, paraphrases)","Each note sits under the heading that fits. Facts about pollen, nectar, and when bees fly go under What Bees Do. Facts about renting hives, trucks, and how many hives per acre go under What Growers Do. (categorizes)","Writes both titles, each next to the right note: Why Apples Need Bees and Hives for Hire. (lists sources)"]}]},{id:9,title:"Fix-It Ladder",short:"Grammar",parts:[{std:["L.4.1"],dur:70,dir:"Say each sentence out loud the correct way.",desc:"spoken grammar items (relative pronouns, progressive tense, adjective order, run-ons, confused words)",qs:["The ladder ____ leans on the tree is wobbly. (who or that)","Yesterday at noon, we ____ apples. (pick) Start with were.","Fix the order: a wooden big basket","Spot the mistake and fix it: We filled the basket it was heavy.","____ basket is over ____ by the tree. (their, there, or they’re)"],key:["that (relative pronoun)","were picking (progressive tense)","a big wooden basket (order of adjectives)","It is a run-on. Fix: We filled the basket. It was heavy. Also accept: We filled the basket, and it was heavy. (fixing a run-on)","Their basket is over there by the tree. (frequently confused words)"]}]},{id:10,title:"Farm Stand Writer",short:"Write",parts:[{alt:{group:"write",key:"opinion",label:"Opinion",icon:"💬",hint:"Tell what you think and why"},std:["W.4.1"],n:4,label:"checks met",dur:270,dir:WRITE_DIR,desc:"an opinion writing piece",html:()=>`<p class="big">Would you rather spend a fall day picking apples in the trees or selling them at the farm stand? Write your opinion. Write 5 to 7 sentences.</p><ul class="qlist" style="margin-top:14px"><li>State your opinion</li><li>Give reasons with facts or details</li><li>Use linking words: for instance, in addition, in order to</li><li>End with a concluding sentence</li></ul>`,key:["Introduces the topic and states an opinion","Gives reasons supported by facts and details","Links opinion and reasons with words like for instance, in order to, in addition","Ends with a concluding statement"]},{alt:{group:"write",key:"facts",label:"Facts",icon:"🐝",hint:"Explain how bees help an orchard"},std:["W.4.2"],n:4,label:"checks met",dur:270,dir:WRITE_DIR,desc:"an informative writing piece",html:()=>`<p class="big">How do honeybees help an apple orchard? Write to explain it. Use facts from the two texts. Write 5 to 7 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Introduce your topic</li><li>Give facts, details, or examples</li><li>Use linking words: for example, also, because</li><li>End with a concluding sentence</li></ul>${lookBackTexts()}`,key:["Introduces the topic clearly","Develops the topic with facts, details, or examples from the texts, such as pollen on the bee, blossoms turning into apples, or rented hives","Links ideas with words like for example, also, because, another","Ends with a concluding statement"]},{alt:{group:"write",key:"story",label:"Story",icon:"📖",hint:"Tell a real or made-up story"},std:["W.4.3"],n:4,label:"checks met",dur:270,dir:WRITE_DIR,desc:"a narrative writing piece",html:()=>`<p class="big">Write a story about a day at an orchard when something went wrong and then got fixed. It can be real or made up. Write 5 to 7 sentences.</p><ul class="qlist" style="margin-top:14px"><li>Start by telling who is in the story and where they are</li><li>Tell what happens in order. Use words like first, next, after that, finally</li><li>Add details: what people said, saw, or felt</li><li>Give your story an ending</li></ul>`,key:["Sets up the situation and introduces a narrator or characters","Events unfold in a clear order, with transition words like first, next, after that, finally","Uses dialogue or description with concrete or sensory details","Ends with a conclusion that follows from the events"]}]},{id:11,title:"Cider Compare",short:"Compare",parts:[{std:["4.NF.A.2"],dur:160,dir:"Answer out loud and tell how you know. Write number 2 on your paper and hold it up.",desc:"comparing fractions with different numerators and denominators",qs:["Which is greater: 2/5 or 7/10? How do you know?","Write &gt;, &lt;, or = to make it true: 3/4 ____ 5/6","Which is greater: 3/8 or 3/5? Tell how you know without drawing.","Would you rather have 4/10 of a jug of cider or 5/8 of the same jug? Why?","Look at the jugs. Ana drank 1/2 of the small jug. Ben drank 1/2 of the big jug. Ana says they drank the same amount. Is she right? Explain."],fig2:()=>`<div class="figure">${jugs()}</div>`,key:["7/10. 2/5 is the same as 4/10, and 4/10 is less than 7/10. Partial: naming 7/10 with no common denominator shown is approaching.","3/4 is less than 5/6. Shows 9/12 and 10/12, or says 5/6 is closer to 1 whole. Or: compare both with 1 whole, since 5/6 is 1/6 short and 3/4 is 1/4 short.","3/5. Both have 3 pieces, but fifths are bigger pieces than eighths. Partial: naming 3/5 with nothing said about the size of the pieces is approaching.","5/8, if you want more cider. 5/8 is more than half and 4/10 is less than half. Either pick is fine when the comparison is right. Partial: a pick given with no comparison is approaching.","No. The jugs are different sizes, so half of the big jug is more. You can only compare fractions this way when the wholes are the same size. Partial: saying no with nothing said about the wholes being the same size is approaching."]}]},{id:12,title:"Tell It at the Farm Stand",short:"Report",parts:[{std:["SL.4.4"],n:4,label:"checks met",dur:80,dir:"Talk for about one minute. Speak clearly and take your time.",desc:"telling about an experience out loud in an organized way with facts and details",html:()=>`<p class="big">Tell me about a place you have visited. It could be a farm, a park, a market, or anywhere you like. Tell it so I can picture it.</p><div class="row center" style="margin-top:20px;gap:18px"><span class="pill" style="font-size:1.4rem">Where and when</span><span class="pill" style="font-size:1.4rem">What happened, in order</span><span class="pill" style="font-size:1.4rem">Details: see, hear, smell</span><span class="pill" style="font-size:1.4rem">Ending</span></div>`,key:["Tells it in an organized order with a beginning, middle, and end","Gives facts that fit the place and what happened","Adds relevant, descriptive details that support the main idea","Speaks clearly at a pace you can follow"]}]},{id:13,title:"At the Press",short:"The Press",parts:[{std:["SL.4.2"],n:3,dur:45,read:PRESS,dir:"Listen while your teacher reads about the cider press. It is not on your screen. Then say it back in your own words.",desc:"paraphrasing parts of an informational text read aloud",html:()=>`<p class="big" style="text-align:center">Listen only. Your teacher will read about the press at Hillcrest.</p>`,qs:["In your own words, what happens to the apples before they are pressed?","Say the last sentence in your own words.","Now say the whole thing back in two or three sentences of your own."],key:["The apples ride up a belt into a grinder that chops them into a coarse mush. Count it correct only when the words are the student's own. Repeating pomace is fine as long as the rest is reworded (SL.4.2)","A ton of apples gives about 120 gallons of cider. Any accurate rewording counts (SL.4.2)","Keeps the order and the main points: grind, wrap and stack, press, juice runs into a tank below. A retelling that changes a fact is not a paraphrase, so note any changed number (SL.4.2)","Read it once. If you read it again, write that down."]}]},{id:14,title:"Times as Many",short:"Compare x",parts:[{std:["4.OA.A.1"],n:3,dur:45,dir:"Answer out loud. Write the equations on your paper.",desc:"reading and writing a multiplication equation as a comparison",html:()=>`<p class="big" style="text-align:center">A crate holds 40 apples. The big wooden bin holds 400.</p>`,qs:["Write a multiplication equation that compares the bin to the crate.","Say what your equation means, using the words times as many.","Here is another one: 35 = 5 × 7. Say it two different ways using times as many."],key:["400 = 10 × 40, or 40 × 10 = 400. Partial: 400 − 40 = 360 is a difference and not a multiplicative comparison, so it does not count. (4.OA.A.1)","The bin holds 10 times as many apples as the crate. Partial: naming the comparison without the words times as many is approaching. (4.OA.A.1)","35 is 5 times as many as 7, and 35 is 7 times as many as 5. Both are needed. Partial: one of the two ways given is approaching. (4.OA.A.1)"]}]},{id:15,title:"Decimal Jugs",short:"Decimals",parts:[{title:"Write It as a Decimal",std:["4.NF.C.6"],n:3,dur:45,dir:"Answer out loud. Write each one on your paper.",desc:"writing fractions with denominators of 10 and 100 as decimals, and decimals as fractions",fig:()=>`<div class="figure">${F.gridRect(10,10,45,{cell:26})}</div>`,qs:["The grid has 100 squares and 45 are shaded. Write that as a fraction, then as a decimal.","Write 7/10 as a decimal.","Write 0.60 as a fraction with 100 on the bottom. Then as a fraction with 10 on the bottom."],key:["45/100 and 0.45. Partial: one of the fraction and the decimal given is approaching. (4.NF.C.6)","0.7. Writing 0.70 is correct too, and the student should be able to say why they are the same. Partial: 0.70 given with no account of why it is the same is approaching. (4.NF.C.6)","60/100 and 6/10. Partial: one of the two fractions given is approaching. (4.NF.C.6)"]},{title:"Which Is More",std:["4.NF.C.7"],n:3,dur:45,dir:"Answer out loud. Use the words greater than, less than, or equal to.",desc:"comparing two decimals to hundredths and justifying the comparison",html:()=>`<p class="big" style="text-align:center">0.7 and 0.68</p>`,qs:["Which is greater, 0.7 or 0.68? Tell how you know.","Compare 0.3 and 0.30.","Put these in order from least to greatest: 0.5, 0.45, 0.54"],key:["0.7 is greater. 0.7 is the same as 0.70, and 70 hundredths is more than 68 hundredths. Saying 68 is a bigger number so 0.68 wins is the classic mistake. Partial: naming 0.7 with no reason from hundredths is approaching. (4.NF.C.7)","They are equal. 3 tenths is the same as 30 hundredths. Partial: saying equal with no reason is approaching. (4.NF.C.7)","0.45, 0.5, 0.54. Comparing them as 45, 50 and 54 hundredths is the reasoning to listen for. Or: line all three up as hundredths, 45, 50, 54. Partial: two of the three in order is approaching. (4.NF.C.7)","Two decimals can only be compared this way when they refer to the same whole. Say so if the student brings it up."]}]},{id:16,title:"Measure the Orchard",short:"Units",parts:[{title:"Bigger Unit, Smaller Unit",std:["4.MD.A.1"],n:3,dur:45,dir:"Look at the table. Answer out loud.",desc:"knowing relative sizes of units and changing a larger unit into a smaller one",fig:()=>F.table(["Pounds","Ounces"],[["1","16"],["2","32"],["3","?"],["5","?"]],{caption:"Weight of apple bags"}),qs:["Finish the table. How many ounces are in 3 pounds? In 5 pounds?","Which is heavier, 40 ounces or 3 pounds? Tell how you know.","The wagon ride takes 2 hours. How many minutes is that?"],key:["48 ounces and 80 ounces (3 × 16 = 48, 5 × 16 = 80). Partial: one of the two rows right is approaching. (4.MD.A.1)","3 pounds is heavier. 3 pounds is 48 ounces, and 48 ounces is more than 40 ounces. The two have to be changed into the same unit before they can be compared. Partial: naming 3 pounds with no change into the same unit is approaching. (4.MD.A.1)","120 minutes (2 × 60). Partial: 120 with no unit named is approaching. (4.MD.A.1)"]},{title:"Around and Inside",std:["4.MD.A.3"],n:3,dur:45,dir:"Look at the apple patch. Answer out loud. Show your work on your paper.",desc:"using the area and perimeter formulas for a rectangle, including finding a missing side",fig:()=>`<div class="figure">${F.rect(12,7,"ft")}</div>`,qs:["What is the area of the patch?","How much fence goes all the way around it?","A different patch has an area of 56 square feet and one side is 8 feet. How long is the other side?"],key:["84 square feet (12 × 7). Partial: 84 with no square unit named is approaching. (4.MD.A.3)","38 feet (12 + 7 + 12 + 7, or 2 × 12 + 2 × 7). Partial: 19 adds only one of each side and does not count. (4.MD.A.3)","7 feet (56 ÷ 8). Partial: 7 with no unit named is approaching. (4.MD.A.3)","Square feet for area and feet for perimeter. Note it when the unit is missing or mixed up."]}]},{id:17,title:"Sign Shapes",short:"Shapes",parts:[{std:["4.G.A.2"],n:3,dur:45,dir:"Look at the four signs. Answer out loud.",desc:"classifying figures by parallel and perpendicular sides and by angle type, including right triangles",fig:()=>`<div class="figure" style="gap:16px">${[[F.poly([[12,88],[12,16],[86,88]],{size:150,alt:"Right triangle",rightAngles:[[12,88,1,-1]]}),"1"],[F.poly([[50,14],[88,88],[12,88]],{size:150,alt:"Acute triangle"}),"2"],[F.poly([[28,16],[96,16],[72,88],[4,88]],{size:150,alt:"Parallelogram"}),"3"],[F.poly([[4,30],[96,30],[96,80],[4,80]],{size:150,alt:"Rectangle"}),"4"]].map(p=>`<div style="text-align:center">${p[0]}<p class="fig-label" style="margin:2px 0 0">${p[1]}</p></div>`).join("")}</div>`,qs:["Which sign has a right angle in it? What do we call that kind of triangle?","Which signs have two pairs of parallel sides?","Sign 2 is a triangle with no right angle. Say one true thing about its angles."],key:["Sign 1, and it is a right triangle. The little square in the corner marks the right angle. Partial: naming the sign with no name for the triangle is approaching. (4.G.A.2)","Signs 3 and 4. Sign 3 is a parallelogram and sign 4 is a rectangle. Sign 4 also has perpendicular sides. Partial: one of the two signs named is approaching. (4.G.A.2)","All three of its angles are acute, which means each one is smaller than a right angle. Any true statement about the angles counts. Partial: naming the angles acute with no account of what acute means is approaching. (4.G.A.2)"]}]},{id:18,title:"Parts of the Orchard",short:"Structures",parts:[{std:["4-LS1-1"],n:3,dur:75,dir:"Look at the apple tree and the bee. Answer out loud or in writing.",desc:"arguing that named plant and animal structures do a job that supports survival, growth or reproduction",html:()=>`<p class="big">An apple tree and a honeybee work together in the orchard. Every part of a living thing is a structure, inside or outside.</p>
     <div class="figure">${F.icon("apple",104)}${F.icon("bee",104)}</div>`,qs:["The apple tree has bark on the outside and seeds inside the fruit. Name the job of each one.","A honeybee's body is covered in fine hairs. Build an argument that these hairs matter to the apple tree as well as to the bee.","Name one more structure of either living thing and say how it supports survival or growth."],key:["Bark covers the trunk and protects the living wood underneath from drying out, insects and weather. Seeds carry the next generation of trees, so they support reproduction. Both parts named with a job. (4-LS1-1)","Pollen sticks to the hairs while the bee drinks nectar, and rubs off at the next blossom. Without pollen moving between trees a blossom dries up instead of growing into an apple. Listen for the claim plus that chain of reasoning. (4-LS1-1)","Any real structure with a job: roots take in water and minerals and anchor the tree, leaves catch sunlight to make food, blossoms attract bees, wings let the bee reach far trees, the bee's tongue reaches nectar deep in a blossom. (4-LS1-1)"]},{std:["4-LS1-2"],n:3,dur:75,dir:"Read what happens, then answer. You may draw your model.",desc:"modelling the path from sense organ to brain to response in an animal",html:()=>`<p class="big">The orchard dog is asleep by the barn door. A raccoon climbs into the apple bins across the yard. The dog lifts its head, turns toward the bins, and runs across the yard barking.</p>
     <div class="figure">${F.icon("dog",104)}${F.icon("raccoon",104)}</div>`,qs:["Name two senses the dog could have used. The body part that takes in each one.","The dog had been asleep. What work did its brain do before its legs moved?","Make a model of the path the information took. Use three labelled steps."],key:["Hearing through the ears and smell through the nose. Accept sight through the eyes once the dog had its head up. (4-LS1-2)","The brain took in the signal, worked out what it meant and which direction it came from, and chose the response. The ears and nose only collect information, they do not decide. (4-LS1-2)","Sense organ takes in information, brain processes it and chooses, body responds. A model that skips the brain is approaching, not proficient. (4-LS1-2)"]}]},{id:19,title:"The Creek Bank",short:"Rock Layers",parts:[{std:["4-ESS1-1"],n:3,dur:90,dir:"Study the bank the creek has cut. Answer out loud or in writing.",desc:"reading rock layers and the fossils in them as evidence of landscape change",html:()=>`<p class="big">The creek at the edge of the orchard has cut down through four layers. Layers pile up with the newest on top.</p>
     <table class="bigTable"><tr><th>Layer</th><th>What the rock is like</th><th>Fossils found in it</th></tr>
     <tr><td>top</td><td>dark garden soil</td><td>apple wood and roots</td></tr>
     <tr><td>second</td><td>rounded gravel</td><td>river snail shells</td></tr>
     <tr><td>third</td><td>fine grey clay</td><td>reed stems and pond snails</td></tr>
     <tr><td>bottom</td><td>cracked lava rock</td><td>none</td></tr></table>`,qs:["Which layer is the oldest, and what in the chart tells you so?","The second layer is rounded gravel with river snails. What was happening at this spot while that layer formed?","Tell the story of this place from the bottom layer to the top."],key:["The bottom layer, the lava rock. The newest layers rest on top, so the lowest one was there first. (4-ESS1-1)","A river or fast stream ran here. Gravel gets rounded by tumbling in moving water, and river snails live in moving water. (4-ESS1-1)","Lava hardened into rock, then a still pond with reeds covered it, then a faster stream laid down rounded gravel, then soil built up on top and trees grew. Any order that follows the chart upward and names the changes counts. (4-ESS1-1)"]},{std:["4-ESS2-1"],n:3,dur:75,dir:"Look at the measurements. Answer out loud or in writing.",desc:"using measurements to compare the rate of erosion under different conditions",html:()=>`<p class="big">The orchard road washes out every winter. The crew set four identical trays of soil on the same slope and ran water over each for five minutes, then weighed the soil in the catch bucket.</p>
     <table class="bigTable"><tr><th>Tray</th><th>Cover on the soil</th><th>Soil in the bucket</th></tr>
     <tr><td>1</td><td>bare soil</td><td>86 grams</td></tr>
     <tr><td>2</td><td>a layer of straw</td><td>24 grams</td></tr>
     <tr><td>3</td><td>grass growing in it</td><td>11 grams</td></tr>
     <tr><td>4</td><td>bare soil, water run at twice the speed</td><td>159 grams</td></tr></table>`,qs:["Which cover slowed the erosion most? Use the numbers.","Compare tray 1 and tray 4. What does that pair show about the water itself?","The crew wants to know whether straw or grass is the better fix. Which two trays answer that, and what is the answer?"],key:["Grass, 11 grams compared with 86 grams of bare soil. The roots hold the grains and the leaves break the force of the water. (4-ESS2-1)","Faster water erodes more: the same bare soil lost 86 grams at the slower speed and 159 grams at twice the speed. The speed of the water is what changed. (4-ESS2-1)","Trays 2 and 3. Grass, because 11 grams is less than 24 grams and everything else about those two trays was the same. (4-ESS2-1)"]}]},{id:20,title:"Mapping the Valley",short:"Map Patterns",parts:[{std:["4-ESS2-2"],n:3,dur:90,dir:"Study the chart from the county map. Answer out loud or in writing.",desc:"interpreting map data to describe patterns in Earth's features",html:()=>`<p class="big">A county map gives the height of the land along a straight line of six places, from the river in the west to the ridge in the east.</p>
     <div class="figure">${F.icon("tree",80)}${F.icon("mountain",80)}${F.icon("drop",80)}</div>
     <table class="bigTable"><tr><th>Place</th><th>Height above sea level</th><th>What the map shows there</th></tr>
     <tr><td>1 west</td><td>12 m</td><td>river, marsh symbols</td></tr>
     <tr><td>2</td><td>38 m</td><td>orchards</td></tr>
     <tr><td>3</td><td>95 m</td><td>orchards, one creek</td></tr>
     <tr><td>4</td><td>240 m</td><td>two creeks, steep lines close together</td></tr>
     <tr><td>5</td><td>580 m</td><td>forest</td></tr>
     <tr><td>6 east</td><td>910 m</td><td>bare ridge top</td></tr></table>`,qs:["Describe the pattern in the land from place 1 to place 6.","At place 4 the map's height lines are drawn close together. What does that tell you about the land there?","The orchards are at places 2 and 3 only. Use the map data to explain why they are there and not at place 6."],key:["The land climbs steadily from west to east, from 12 metres at the river to 910 metres at the ridge. (4-ESS2-2)","The land is steep there. Lines close together mean the height changes a lot over a short distance, which is why two creeks run down through it. (4-ESS2-2)","Places 2 and 3 are low, fairly flat and near water, which orchards need. Place 6 is a bare ridge top at 910 metres, too high, too steep and too exposed. The answer has to use numbers or symbols from the chart. (4-ESS2-2)"]},{std:["4-ESS3-2"],n:3,dur:95,dir:"Read the two plans. Answer out loud or in writing.",desc:"generating and comparing solutions that reduce the impact of a natural Earth process",html:()=>`<p class="big">Every few winters the creek rises and water stands in the lowest row of trees until the roots rot. The orchard can do one thing this year.</p>
     <table class="bigTable"><tr><th>Plan</th><th>What it does</th><th>Cost</th><th>Effect on the orchard</th></tr>
     <tr><td>A: dig a drainage ditch along the low row</td><td>carries standing water away to the creek below the orchard</td><td>medium</td><td>loses one row of trees to the ditch</td></tr>
     <tr><td>B: build up the low row into a raised mound</td><td>lifts the roots above the water level</td><td>high</td><td>keeps every tree, slow to build</td></tr></table>`,qs:["Add a third plan of your own that would reduce the effect of the flooding.","Compare plan A and plan B. Which would you choose. What in the chart supports your choice?","Now take the plan you did not choose. Name one thing that plan does better than the one you picked."],key:["Any workable idea: plant that low row with a tree that tolerates wet roots, leave the low row as a flood basin on purpose, put in an underground drain line, widen the creek channel upstream, build a low bank between the creek and the orchard. (4-ESS3-2)","Either plan, judged on the chart. Plan A costs less and works at once but gives up a row of trees. Plan B keeps all the trees but costs the most and takes longer. The reason drawn from the chart is what is rated, not the plan picked. (4-ESS3-2)","The plan turned down has to be credited with something real from the chart. A student who chose A should say that B keeps every tree. A student who chose B should say that A costs less, or that A works this year while the mound is slow to build. Or: any other advantage the chart supports counts. Partial: saying the other plan is simply worse, with nothing it does better, is approaching, because comparing solutions means weighing both sides of each one and not only the winner. (4-ESS3-2)"]}]},{id:21,title:"Power for the Press",short:"Energy Sources",parts:[{std:["4-ESS3-1"],n:3,dur:90,dir:"Study the chart. Answer out loud or in writing.",desc:"describing where energy and fuels come from and how using them affects the environment",html:()=>`<p class="big">The cider press can be run four ways. The orchard keeps a chart before deciding.</p>
     <table class="bigTable"><tr><th>Way to run it</th><th>Natural resource it comes from</th><th>Runs out?</th><th>One effect on the environment</th></tr>
     <tr><td>petrol engine</td><td>oil from deep underground</td><td>yes</td><td>exhaust into the air</td></tr>
     <tr><td>wood fired steam</td><td>trees</td><td>yes, if cut faster than they grow</td><td>smoke, fewer trees</td></tr>
     <tr><td>water wheel on the creek</td><td>moving water from rain and snowmelt</td><td>no, but the creek runs low in summer</td><td>changes the creek channel, blocks fish</td></tr>
     <tr><td>roof panels</td><td>sunlight</td><td>no</td><td>roof space used, panels must be made and shipped</td></tr></table>`,qs:["Trace the petrol engine back to its natural resource. Where did that resource come from?","Two of these four will not run out. Name them and say why the supply keeps coming.","The orchard switches from the petrol engine to the water wheel. Name one effect that gets smaller and one new effect that appears."],key:["Petrol is refined from oil, which is pumped from deep underground. Oil formed from the remains of tiny living things buried for millions of years. Tracing it back to oil under the ground is enough at this grade. (4-ESS3-1)","The water wheel and the roof panels. Rain and snow keep refilling the creek and the sun keeps shining, so the supply is renewed rather than used up. (4-ESS3-1)","Exhaust into the air gets smaller. The new effect is in the chart: the wheel changes the creek channel and can block fish, and the creek runs low in summer so the press may stop. Naming only the benefit is approaching. (4-ESS3-1)"]}]},{id:22,title:"Down the Orchard Hill",short:"Speed",parts:[{std:["4-PS3-1"],n:3,dur:75,dir:"Look at the results. Answer out loud or in writing.",desc:"using evidence to explain how the speed of an object relates to its energy",html:()=>`<p class="big">The same loaded apple wagon was let go from three places on the orchard hill. At the bottom each one rolled into a hay bale and pushed it along the ground.</p>
     <table class="bigTable"><tr><th>Start</th><th>Speed at the bottom</th><th>Hay bale pushed</th></tr>
     <tr><td>low on the hill</td><td>2 metres each second</td><td>6 cm</td></tr>
     <tr><td>halfway up</td><td>4 metres each second</td><td>23 cm</td></tr>
     <tr><td>top of the hill</td><td>6 metres each second</td><td>52 cm</td></tr></table>`,qs:["What happens to the distance the bale is pushed as the speed goes up?","Which wagon carried the most energy? Name the measurement that is your evidence.","The speeds go up by 2 each time. Do the push distances go up by the same amount each time? What does that tell you?"],key:["It gets much larger: 6 cm, then 23 cm, then 52 cm. (4-PS3-1)","The one from the top of the hill, at 6 metres each second. It pushed the bale 52 cm, farther than either other wagon, so it had more energy to give. (4-PS3-1)","No. The jumps are 17 cm and then 29 cm, so the distance grows faster than the speed does. A faster object does not just have a little more energy, it has a lot more. Noticing the uneven jumps is the heart of this item. (4-PS3-1)"]},{std:["4-PS3-3"],n:3,dur:75,dir:"Answer out loud or in writing. A prediction only needs a reason, not the right answer.",desc:"asking a question and predicting the energy change in a collision",html:()=>`<p class="big">Apples roll down a wooden chute into a crate. A heavy apple is rolling down behind a light one, and it catches up and hits it.</p>
     <div class="figure">${F.icon("apple",96)}${F.icon("apple",96)}</div>`,qs:["Ask one question about this collision that a test could answer.","Predict what happens to the light apple and to the heavy one when they hit.","Apples bruise when energy goes into the fruit instead of into motion. Predict which apple is more likely to bruise, and say why."],key:["Any testable question: how far does the light apple shoot forward, does the bruise get worse if the chute is steeper, does a padded chute change the sound, what happens if both apples are heavy. (4-PS3-3)","The light apple is pushed forward and speeds up. The heavy apple slows down. Both halves make the full prediction. (4-PS3-3)","Either apple, with reasoning. The light one is pushed hardest so more energy goes into it, and it may hit the crate harder at the end. A student who argues the heavy one bruises because all its energy stops at the moment of contact is also reasoning about where the energy goes, which is what this standard asks. (4-PS3-3)"]}]},{id:23,title:"Energy in the Barn",short:"Transfer",parts:[{std:["4-PS3-2"],n:4,dur:75,dir:"For each observation, say how the energy travelled. Answer out loud or in writing.",desc:"matching observations to energy transferred by sound, light, heat or electric current",html:()=>`<p class="big">Four things noticed in the packing barn in one afternoon.</p>
     <table class="bigTable"><tr><th></th><th>What was noticed</th></tr>
     <tr><td>1</td><td>The press motor is switched on and the whole barn fills with a low hum.</td></tr>
     <tr><td>2</td><td>A crate of apples left on the sunny side of the yard is warm on top and cool underneath.</td></tr>
     <tr><td>3</td><td>The sorting lamp is turned on and the far corner of the barn becomes bright.</td></tr>
     <tr><td>4</td><td>A cord runs from the wall to the fan, and the blades start to spin.</td></tr></table>`,qs:["How did the energy travel in observation 1?","How did it travel in observation 2?","How did it travel in observation 3?","How did it travel in observation 4?"],key:["By sound, through the air from the motor to every ear in the barn. (4-PS3-2)","By heat, carried in sunlight to the top apples and then along from apple to apple. Accept light as the way it crossed the yard and heat as what moved into the crate. (4-PS3-2)","By light, from the lamp across the barn to the far corner. (4-PS3-2)","By an electric current, through the cord from the wall to the fan motor, where it becomes motion. (4-PS3-2)"]},{std:["4-PS3-4"],n:3,dur:90,dir:"Draw your device and label it. Then answer out loud or in writing.",desc:"designing, testing and improving a device that converts energy from one form to another",html:()=>`<p class="big">The apple washing tub needs a small fan to dry the fruit. There is no outlet near the tub. Design a device that turns one kind of energy into the spinning of a fan. You may use a hand crank, a belt, a paddle wheel in the creek, a battery and wire, or a weight on a string.</p>
     <div class="figure">${F.icon("wateringCan",96)}${F.icon("wind",96)}</div>`,qs:["Draw and label your device. Show the path from the energy going in to the fan turning.","Name the kind of energy going in and the kind coming out.","You test it and the fan turns too slowly. Name one change you would make and say why it should help."],key:["Any labelled drawing with a path: a paddle wheel in the creek, a belt, and the fan; or a battery, wire, and a small motor on the fan. Labels and a path through the device are what make it a design. (4-PS3-4)","Going in: motion of the water or the crank, or electrical energy from the battery. Coming out: motion of the fan, plus some sound and heat. Both forms named. (4-PS3-4)","Any change with a reason: a bigger paddle wheel to catch more water, a smaller pulley on the fan so it turns more times per crank, a fresh battery, less friction in the bearing, a steeper fall of water. A change without a reason is approaching. (4-PS3-4)"]}]},{id:24,title:"Ripples, Colour and Signals",short:"Waves",parts:[{std:["4-PS4-1"],n:3,dur:75,dir:"Look at the two drawings of the water. Answer out loud or in writing.",desc:"using a wave model to describe amplitude and wavelength and the effect on a floating object",html:()=>`<p class="big">A leaf floats in the washing tub. The crew drew the surface twice: once when one apple was dropped in gently, and once when a full crate was tipped in.</p>
     <div class="figure"><svg viewBox="0 0 520 300" width="520" role="img" aria-label="Two waves drawn above one another with letters A and B marking parts of the first wave">
       <text x="10" y="18" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">one apple</text>
       <line x1="20" y1="70" x2="500" y2="70" stroke="var(--line)" stroke-width="2" stroke-dasharray="6 6"/>
       <path d="M20 70 q30 -30 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0" fill="none" stroke="var(--sea)" stroke-width="5"/>
       <line x1="50" y1="70" x2="50" y2="55" stroke="var(--coral)" stroke-width="4"/>
       <text x="62" y="62" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">A</text>
       <line x1="20" y1="112" x2="140" y2="112" stroke="var(--coral)" stroke-width="4"/>
       <text x="80" y="134" font-size="22" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif" text-anchor="middle">B</text>
       <text x="10" y="186" font-size="20" font-weight="700" fill="var(--ink)" font-family="Andika,sans-serif">a full crate</text>
       <line x1="20" y1="240" x2="500" y2="240" stroke="var(--line)" stroke-width="2" stroke-dasharray="6 6"/>
       <path d="M20 240 q30 -80 60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0 t60 0" fill="none" stroke="var(--sea)" stroke-width="5"/>
     </svg></div>`,qs:["Which letter marks the wavelength, and which marks the amplitude?","Which measurement changed when the crate went in instead of one apple? Did it grow or shrink?","What does the change do to the floating leaf?"],key:["B marks the wavelength, from one wave to the next one like it. A marks the amplitude, from the flat line up to the crest. (4-PS4-1)","The amplitude grew. The crests are much taller in the second drawing. The wavelength stayed the same, which is worth pointing out if the student misses it. (4-PS4-1)","The leaf rises and falls much farther, because a bigger amplitude carries more energy. It still bobs up and down roughly in place rather than riding along with the wave. (4-PS4-1)"]},{std:["4-PS4-2"],n:3,dur:75,dir:"Answer out loud or in writing. You may draw arrows.",desc:"modelling how light reflects from an object into the eye so the object can be seen",html:()=>`<p class="big">Two apples sit on the sorting table under the barn lamp, one red and one green. When the lamp is switched off the barn is completely dark.</p>
     <div class="figure">${F.icon("apple",96)}${F.icon("apple",96)}</div>`,qs:["Draw or tell the path the light takes when a sorter sees the red apple. Name every place it goes.","In the completely dark barn the apples have not moved. Why can nobody see them?","A sorter says the red apple is glowing. What would you say back, and what evidence would you use?"],key:["Light leaves the lamp, travels to the apple, reflects off the apple, and travels into the eye. All three legs are needed. (4-PS4-2)","With the lamp off there is no light to reflect off them, so no light reaches anybody's eye. An object has to send light to the eye to be seen. (4-PS4-2)","It is not making its own light, it is reflecting the lamp's light. The evidence is that it cannot be seen at all once the lamp is off, while something that made its own light would still show. (4-PS4-2)"]},{std:["4-PS4-3"],n:3,dur:75,dir:"Read the two systems. Answer out loud or in writing.",desc:"comparing two solutions that use patterns to send information",html:()=>`<p class="big">The pickers are spread across the far rows and need three messages from the barn: bring a load in, take a break, and come to the barn now.</p>
     <table class="bigTable"><tr><th>System</th><th>How a message is sent</th><th>Needs</th></tr>
     <tr><td>Barn bell</td><td>one ring, two rings, or a long string of rings</td><td>carries about 400 metres, works in fog and in the dark</td></tr>
     <tr><td>Coloured flag on the barn roof</td><td>a yellow flag, a blue flag, or a red flag</td><td>needs daylight and a clear line of sight down the row</td></tr></table>`,qs:["Name the pattern that carries the information in each system.","A picker is working in the far rows where trees block the view of the barn. Which system reaches them, and why?","Design a third system of your own for the same three messages, using neither sound nor a flag."],key:["In the bell system the pattern is how many rings and how long they go on. In the flag system the pattern is which colour is flying. An agreed pattern standing for a message is what transfers the information. (4-PS4-3)","The bell, because sound travels around and through the trees while a flag needs a clear line of sight. (4-PS4-3)","Any pattern with three agreed signals: three lamp flash patterns at dusk, a note passed with one, two or three marks, a radio with three agreed words, a pattern of taps on the water pipe, three positions of a gate. Three distinct signals are required. (4-PS4-3)"]}]},{id:25,title:"A Chute That Does Not Bruise",short:"Design",parts:[{std:["3-5-ETS1-1"],n:3,dur:60,dir:"Read the situation, then answer out loud or in writing.",desc:"defining a design problem with criteria for success and constraints",html:()=>`<p class="big">Apples come off the ladder into a chute and drop into the crate. About one in six arrives bruised. The crew has one morning, scrap wood, old blankets, and no money to spend.</p>
     <div class="figure">${F.icon("apple",88)}${F.icon("box",88)}</div>`,qs:["State the problem in one sentence, in your own words.","Write two criteria: how will the crew know the new chute works?","Write two constraints from the situation."],key:["Something like: apples need to reach the crate without being bruised. A problem statement, not a solution. (3-5-ETS1-1)","Any two testable criteria: fewer than one bruised apple in twenty, apples still reach the crate without being carried by hand, the chute is no slower than the old one, one person can work it. (3-5-ETS1-1)","One morning, only scrap wood and old blankets, no money. Any two. Naming a criterion here instead shows the two ideas are mixed and is approaching. (3-5-ETS1-1)"]},{std:["3-5-ETS1-2"],n:3,dur:75,dir:"Study the three designs. Answer out loud or in writing.",desc:"generating and comparing solutions against the criteria and constraints",html:()=>`<p class="big">Three designs for the chute.</p>
     <table class="bigTable"><tr><th>Design</th><th>What it is</th><th>Materials</th><th>Build time</th></tr>
     <tr><td>1</td><td>line the chute with an old blanket</td><td>a blanket</td><td>short</td></tr>
     <tr><td>2</td><td>add three gentle bends so apples slow down on the way</td><td>scrap wood</td><td>half a morning</td></tr>
     <tr><td>3</td><td>fit a small electric belt that carries each apple down</td><td>a belt and a motor to buy</td><td>two days</td></tr></table>`,qs:["Which design breaks a constraint? Name the constraint.","Compare designs 1 and 2 against the criteria. Which do you expect to bruise fewer apples, and why?","Add a fourth idea of your own that fits the materials and the time."],key:["Design 3. It needs a belt and a motor to buy, and there is no money, and two days is longer than the one morning available. (3-5-ETS1-2)","Either, argued from the criteria. The blanket softens the landing at the end, while the bends take speed out along the whole way down, so less energy is left at the bottom. A student who says both together would work best is reasoning well. (3-5-ETS1-2)","Any idea in scrap wood and blankets: pad only the bottom of the chute, make the slope shallower, cut the drop into two short steps with a pad between, hang blanket flaps across the chute to slow the apples, pad the inside of the crate. (3-5-ETS1-2)"]},{std:["3-5-ETS1-3"],n:3,dur:75,dir:"Answer out loud or in writing.",desc:"planning a fair test with controlled variables and naming a failure point",html:()=>`<p class="big">The crew wants to find out whether the blanket lining or the bends bruise fewer apples. They have two chutes and plenty of apples.</p>
     <div class="figure">${F.icon("apple",96)}${F.icon("board",96)}</div>`,qs:["Plan the test. What will you count or measure?","Name two things you must keep the same in both chutes so the test is fair.","Name one failure point: the place where your design is most likely to give way or stop working."],key:["Count the bruised apples out of the same number sent down each chute, for example 20 apples each, checked the same way. A measured or counted result, not a feeling. (3-5-ETS1-3)","Any two: the same number of apples, the same kind and ripeness of apple, the same height at the top, the same slope, the same crate at the bottom, the same person loading. Only the chute design should differ. (3-5-ETS1-3)","Any sensible weak spot: the blanket bunches up and jams the chute, the bends catch and stop an apple, the blanket gets wet and dirty, apples pile up at a bend and knock each other, the scrap wood joint works loose. (3-5-ETS1-3)"]}]},{id:26,title:"Where Things Grow",short:"Regions",parts:[{std:["HSS-4.1"],n:4,dur:90,dir:"Study the chart of four California places. Answer out loud or in writing.",desc:"describing the physical and human geographic features that define places and regions in California",html:()=>`<p class="big">Four places in California, with what the map and the weather records show.</p>
     <div class="figure">${F.icon("apple",80)}${F.icon("wheat",80)}${F.icon("pine",80)}${F.icon("cactus",80)}</div>
     <table class="bigTable"><tr><th>Place</th><th>Region</th><th>Height</th><th>Rain in a year</th><th>Grown or made there</th></tr>
     <tr><td>Near the coast, north of the bay</td><td>Coast</td><td>60 m</td><td>100 cm</td><td>apples, dairy</td></tr>
     <tr><td>Middle of the Central Valley</td><td>Central Valley</td><td>30 m</td><td>30 cm</td><td>almonds, tomatoes, cotton, with canal water</td></tr>
     <tr><td>High in the Sierra Nevada</td><td>Mountains</td><td>2,100 m</td><td>130 cm, much of it snow</td><td>timber, visitors, stored water</td></tr>
     <tr><td>Mojave, inland and south</td><td>Desert</td><td>900 m</td><td>12 cm</td><td>solar power, some dates with irrigation</td></tr></table>`,qs:["Which place gets the least rain, and which gets the most? Name their regions.","The Central Valley grows the most crops but gets only 30 cm of rain. Explain how that is possible, using the chart.","Name one physical feature and one human feature from the chart. Then say what makes them different kinds of feature.","Fog and cool nights near the coast suit apples. Is that a physical reason or a human reason? Explain."],key:["The Mojave desert place gets the least at 12 cm. The Sierra Nevada place gets the most at 130 cm, much of it as snow. Partial: one of the two places named is approaching. (HSS-4.1)","The water comes from somewhere else. Mountain snow melts and is stored, then canals carry it to the valley fields, so the crops do not depend on the valley's own rain. Partial: saying the water comes from elsewhere with no route named is approaching. (HSS-4.1)","Physical features come from nature: height, rain, snow, rivers. Human features are built or done by people: canals, solar power, timber mills, towns. Both named with the difference stated. Partial: one of each named with no difference stated is approaching. (HSS-4.1)","A physical reason. Fog and cool nights are weather, which is part of the natural setting, not something people built. Partial: the right label with no explanation is approaching. (HSS-4.1)"]}]},{id:27,title:"Trade, Gold and a New State",short:"California Past",parts:[{std:["HSS-4.2"],n:3,dur:195,dir:"Read the chart, then answer out loud or in writing.",desc:"describing the economic and cultural life and the interactions among peoples of early California",html:()=>`<p class="big">What people in California traded and ate, in three periods.</p>
     <table class="bigTable"><tr><th>Period</th><th>Main work</th><th>What was traded, and with whom</th></tr>
     <tr><td>First peoples, before 1769</td><td>gathering acorns, fishing, hunting, making baskets and tools</td><td>shell beads, obsidian for blades, salt and baskets, traded nation to nation along inland routes</td></tr>
     <tr><td>Spanish mission period, 1769 to the 1820s</td><td>wheat and corn farming, cattle, workshops at the missions, worked largely by Native Californians</td><td>supplies carried north and south along El Camino Real between the missions and the towns</td></tr>
     <tr><td>Mexican rancho period, 1820s to 1840s</td><td>cattle on large land grants, worked by Native Californian vaqueros</td><td>cattle hides and tallow traded to ships from the eastern states and Europe for cloth, boots, tools and furniture</td></tr></table>
     <p class="big">Each nation had its own religious beliefs and its own ceremonies, and they differed from nation to nation. Chumash ceremonies were led by trained specialists, and the shell beads that served as money on the coast were used in those ceremonies too. Miwok nations danced in a large round earth covered ceremonial house after the acorn harvest. Some of the goods that moved along the trade routes, such as shell beads and obsidian, were brought for those gatherings rather than for daily use.</p>
     <p class="big">The missions were founded by Franciscan missionaries sent from Spain. Their purpose was to convert Native Californians to Christianity and to teach them Spanish crops, herding and trades. The missionaries directed that work, and the land the missions used had been held by Native Californian nations.</p>`,qs:["Compare how the first peoples got their food with how the ranchos got theirs. Then use the note to name one way the trade goods were connected to a nation's ceremonies.","Each period traded over a longer distance than the one before. Name the distance each one reached.","According to the note, what were the Franciscan missionaries at the missions there to do? Native Californians did most of the work at the missions and later as rancho vaqueros. What does that tell you about how the two groups of people were connected?"],key:["The first peoples gathered, fished and hunted what grew and lived where they were, especially acorns. The ranchos raised huge cattle herds on granted land and traded hides for most of what they did not raise. On the ceremonies: shell beads were used in Chumash ceremonies as well as as money, and shell beads and obsidian travelled the trade routes to be brought to gatherings such as the Miwok dances after the acorn harvest, not only for daily use. Both halves are needed for full credit. Partial: one half without the other is approaching, so the food comparison with nothing on the ceremonies sits there. (HSS-4.2)","The first peoples traded nation to nation across inland California, the missions along El Camino Real up and down the coast of California, the ranchos across the ocean to the eastern states and Europe. Partial: two of the three distances named is approaching. (HSS-4.2)","The Franciscans were sent to convert Native Californians to Christianity and to teach them Spanish crops, herding and trades. On the connection: the mission and rancho economies both depended on Native Californian labour, so the two groups were not separate. The skills and the daily work of Native Californians kept the fields, the herds and the trade going, while the missions and later the rancho families held the land and directed the work. Both halves are needed for full credit. Partial: one half without the other is approaching, so naming the purpose with nothing on the connection sits there. (HSS-4.2)"]},{std:["HSS-4.3"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"explaining the economic, social and political life of California from the Bear Flag Republic through the Gold Rush to statehood",html:()=>`<p class="big">Who came to California in the Gold Rush years, and what happened next.</p>
     <table class="bigTable"><tr><th>Fact</th><th>Detail</th></tr>
     <tr><td>1846, Sonoma</td><td>American settlers declared the Bear Flag Republic. It lasted only weeks before the war between the United States and Mexico reached California.</td></tr>
     <tr><td>1848, Coloma</td><td>Gold was found in the American River. News spread by ship and by letter.</td></tr>
     <tr><td>Who came</td><td>Miners arrived from the eastern states, Mexico, Chile, China, Ireland, France and Australia. Many Native Californians were pushed off their land.</td></tr>
     <tr><td>Who earned most</td><td>Merchants who sold shovels, boots, flour and eggs often made more money than the miners did.</td></tr>
     <tr><td>1850</td><td>California became the 31st state, only two years after the gold was found.</td></tr></table>`,qs:["The Bear Flag Republic lasted only weeks. What brought it to an end?","Why would a shopkeeper in a mining camp make more money than most miners?","The chart says statehood came only two years after the gold was found. Explain how the Gold Rush made that happen so fast."],key:["The war between the United States and Mexico reached California, and California came under the United States instead of standing as its own republic. Partial: naming the war with no account of what California became is approaching. (HSS-4.3)","Every miner needed tools, boots and food, and there were few stores and no local farms or factories, so goods were scarce and prices were very high. Most miners found little gold, while a store sold to all of them. Partial: saying prices were high with no account of why goods were scarce is approaching. (HSS-4.3)","Tens of thousands of people arrived in a year, so there were enough people to be a state and an urgent need for courts, laws and government where almost none existed. The population and the pressure arrived together. Partial: naming the population rise with nothing said about the need for government is approaching. (HSS-4.3)"]}]},{id:28,title:"Shipping, Water and Government",short:"Government",parts:[{std:["HSS-4.4"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"tracing California's growth into an agricultural and industrial power since the 1850s",html:()=>`<p class="big">Four changes that turned California farms into a business selling across the country.</p>
     <table class="bigTable"><tr><th>Change</th><th>What it made possible</th></tr>
     <tr><td>The transcontinental railroad, 1869</td><td>goods and people moved between California and the eastern states in days instead of months</td></tr>
     <tr><td>Refrigerated railcars, from the 1880s</td><td>fruit picked in California arrived in eastern cities still fit to sell</td></tr>
     <tr><td>Irrigation districts and aqueducts, from the 1870s on</td><td>dry valley land became orchards and row crops</td></tr>
     <tr><td>Canneries and packing houses</td><td>fruit was preserved or boxed near the fields, and towns grew around the work</td></tr></table>`,qs:["Why did refrigerated railcars matter so much to a fruit grower?","Pick two changes from the chart and explain how they worked together.","Name one effect these changes had on where people lived or what work they did."],key:["Fruit spoils in a few days. Without cooling it could only be sold nearby, so a grower could not plant more than local people would eat. Cooled cars turned distant cities into customers. Partial: saying fruit spoils with no account of the market it opened is approaching. (HSS-4.4)","Any two linked sensibly: irrigation made more fruit than California could eat, and the railroad and cooled cars carried it away; packing houses needed a railroad to ship from; canneries made it worth growing fruit that would not travel fresh. Partial: two changes named with no link between them is approaching. (HSS-4.4)","Any supported effect: farm towns grew along the railroad and around the canneries, seasonal work drew workers from far away, people moved off small mixed farms into packing and canning jobs, cities grew at the shipping points. Partial: an effect asserted with nothing from the chart behind it is approaching. (HSS-4.4)"]},{std:["HSS-4.5"],n:3,dur:90,dir:"Study the chart, then answer out loud or in writing.",desc:"explaining the structures, functions and powers of local, state and federal government",html:()=>`<p class="big">How a state law is made in California, and who else holds power.</p>
     <table class="bigTable"><tr><th>Step or level</th><th>What happens there</th></tr>
     <tr><td>A bill is written and introduced</td><td>a member of the state Assembly or state Senate puts it forward</td></tr>
     <tr><td>Both houses vote</td><td>the Assembly and the Senate must both pass the same bill</td></tr>
     <tr><td>The governor acts</td><td>signs the bill into law, or rejects it</td></tr>
     <tr><td>The courts</td><td>decide what a law means when people disagree about it</td></tr>
     <tr><td>Local government</td><td>a city council or county board of supervisors sets local rules, roads, parks and libraries</td></tr>
     <tr><td>Federal government</td><td>Congress, the President and the federal courts handle the armed forces, money, mail and treaties</td></tr></table>`,qs:["Name the two houses of the California legislature. Then say what both of them must do before a bill can become law.","Which branch makes laws, which carries them out, and which decides what they mean?","A new library is wanted in your town. Which level of government would decide, and why that level?"],key:["The Assembly and the Senate. Both must pass the same bill before it can go to the governor. Partial: both houses named with nothing said about passing the same bill is approaching. (HSS-4.5)","The legislature makes them, the governor and the state departments carry them out, the courts decide what they mean. All three jobs matched. Partial: two of the three jobs matched is approaching. (HSS-4.5)","Local government, the city council or county board, because libraries, parks and local services are theirs to decide and pay for. A student who adds that the state can also give money toward it is correct. Partial: the level right with no reason is approaching. (HSS-4.5)"]}]}];const LEVELUPS={2:{id:"L2",lv:true,title:"Level Up: One Tenth",std:["5.NBT.A.1"],needs:["4.NBT.A.1"],n:2,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="huge">4,440</p><ol class="qlist"><li>Look at the 4 in the tens place and the 4 in the hundreds place. The 4 in the tens place is worth what fraction of the 4 in the hundreds place?</li><li>Finish the sentence: 600 is 1/10 of ____.</li></ol>`,key:["1/10. 40 is one tenth of 400. A digit is worth 1/10 of what it is worth one place to the left. (5.NBT.A.1)","6,000 (5.NBT.A.1)"]},4:{id:"L4",lv:true,title:"Level Up: Picture Words",std:["RL.5.4"],needs:["RL.4.4"],n:2,dir:"Read the lines to yourself. Then answer out loud.",html:()=>`<p class="passage">The orchard was a green ocean, and the wind made waves in the leaves. High in the branches, the apples hung like tiny red balloons.</p><ol class="qlist"><li>“The orchard was a green ocean.” Is this a simile or a metaphor? What does it mean?</li><li>“The apples hung like tiny red balloons.” Is this a simile or a metaphor? What does it mean?</li></ol>`,key:["Metaphor. It says the orchard is an ocean without using like or as. It means the orchard is wide and green, and the leaves move like water. (RL.5.4)","Simile. It uses the word like. It means the apples are round, bright, and seem to float up high. (RL.5.4)"]},6:{id:"L6",lv:true,title:"Level Up: Quote It",std:["RI.5.1"],needs:["RI.4.1"],n:2,dir:"Find the sentence and read the exact words out loud.",html:()=>`${twoTextsHtml()}<ol class="qlist"><li>Read me the exact sentence from Text 1 that tells what happens to a blossom with no pollen.</li><li>Read me the exact sentence from Text 2 that explains why bees might not fly on a stormy day.</li></ol>`,key:["Reads the exact sentence: A blossom that gets none dries up and falls off. (RI.5.1, quoting accurately)","Reads the exact sentence: Honeybees stay in the hive when it is rainy, windy, or colder than about 55 degrees. (RI.5.1, quoting accurately)"]},11:{id:"L11",lv:true,title:"Level Up: Cider Sums",std:["5.NF.A.2"],needs:["4.NF.A.2"],n:2,dir:"Solve on your paper and hold it up. Then answer number 2 out loud.",html:()=>`<p class="big">Rosa poured 2/3 gallon of cider into a pot. Then she poured in 1/4 gallon more.</p><ol class="qlist"><li>How much cider is in the pot?</li><li>Ty says the answer is 3/7 gallon. Without solving, how can you tell Ty is wrong?</li></ol>`,key:["11/12 gallon (8/12 + 3/12) (5.NF.A.2)","3/7 is less than 1/2. Rosa started with 2/3 gallon, which is already more than 1/2, and then added more. (5.NF.A.2, checking with a benchmark)"]}};const PASSAGE_STD=["RL.4.1","RL.4.4","RI.4.1","RI.4.9","RI.5.1","RL.5.4","W.4.8","W.4.2"];const MULT_N=12,FRAC_DENS=[1,2,3,4,5,6,8,10,12];let multSel=[0,0],pvVal="",pvStop=null,fracOn={};const PV_COLS=["Hundred<br>thousands","Ten<br>thousands","Thousands","Hundreds","Tens","Ones"];const STARTERS={opinion:["I would rather ____ because ____.","One reason is ____.","For instance, ____.","In addition, ____.","That is why ____."],facts:["Honeybees help an orchard by ____.","One fact is ____.","For example, ____.","Also, ____.","In conclusion, ____."],story:["One fall morning, ____.","First, ____.","After that, ____.","Finally, ____.","In the end, ____."]};function multHtml(){let h=`<div class="tool-scroll"><table class="mult"><tr><th>×</th>`;for(let c=1;c<=MULT_N;c++)h+=`<th data-r="0" data-c="${c}" class="${multSel[1]===c?"hl":""}">${c}</th>`;h+="</tr>";for(let r=1;r<=MULT_N;r++){h+=`<tr><th data-r="${r}" data-c="0" class="${multSel[0]===r?"hl":""}">${r}</th>`;for(let c=1;c<=MULT_N;c++){const hr=multSel[0]===r,hc=multSel[1]===c;h+=`<td data-r="${r}" data-c="${c}" class="${hr&&hc?"pick":hr||hc?"hl":""}">${r*c}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to light up its row and column. Click it again to clear.</p>`}function pvTable(){const ip=pvVal.replace(/[^0-9]/g,"");let h="<tr>";PV_COLS.forEach(c=>h+=`<th>${c}</th>`);h+="</tr><tr>";PV_COLS.forEach((c,i)=>{const k=ip.length-(PV_COLS.length-i);h+=`<td>${k>=0?ip[k]:""}</td>`});return h+"</tr>"}function pvHtml(st){pvStop=st;return`<label class="pv-in">Type a number<input type="text" inputmode="numeric" id="pvInput" value="${pvVal}" autocomplete="off"></label><div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div>`}function fracHtml(){return FRAC_DENS.map(d=>{const on=fracOn[d]||0;let r=`<div class="fs-row">`;for(let k=0;k<d;k++)r+=`<button class="fs-part${d>=10?" sm":""}${k<on?" on":""}" data-d="${d}" data-k="${k}">${d===1?"1 whole":"1/"+d}</button>`;return r+"</div>"}).join("")+`<p class="small">Click a piece to shade up to it. Click the last shaded piece to clear the row.</p>`}const SENT_ALIAS={opinion:"W.4.1",facts:"W.4.2",story:"W.4.3","W.4.1":"opinion","W.4.2":"facts","W.4.3":"story"};function sentKey(st){const ps=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const pick=c=>!c?null:STARTERS[c]?c:SENT_ALIAS[c]&&STARTERS[SENT_ALIAS[c]]?SENT_ALIAS[c]:null;for(const p of ps){const a=pick(p.alt&&p.alt.key||p.wk||p.wt);if(a)return a;for(const c of p.std||[]){const k=pick(c);if(k)return k}}return null}function sentHtml(st){const k=sentKey(st);return`<ul class="starters">${(STARTERS[k]||STARTERS.opinion).map(x=>`<li>${x}</li>`).join("")}</ul>`}const TOOLS={mult:{name:"Multiplication chart",std:["4.NF.A.1","4.NF.A.2","4.OA.A.1","4.MD.A.1","4.MD.A.3","5.NF.A.2"],html:multHtml,bind:(b,r)=>b.querySelectorAll("[data-r]").forEach(c=>c.onclick=()=>{const rr=+c.dataset.r,k=+c.dataset.c;multSel=multSel[0]===rr&&multSel[1]===k?[0,0]:[rr,k];r()})},pv:{name:"Place value chart",std:["4.NBT.A.1","4.NBT.A.3","4.NF.C.6","4.NF.C.7"],html:pvHtml,bind:(b,r,st)=>{const inp=b.querySelector("#pvInput"),tb=b.querySelector("#pvTable");if(inp&&tb)inp.oninput=()=>{pvVal=inp.value.replace(/[^0-9,]/g,"");tb.innerHTML=pvTable()}}},frac:{name:"Fraction strips",std:["4.NF.A.1","4.NF.A.2","4.NF.C.6","5.NF.A.2"],html:fracHtml,bind:(b,r)=>b.querySelectorAll(".fs-part").forEach(x=>x.onclick=()=>{const d=+x.dataset.d,k=+x.dataset.k;fracOn[d]=fracOn[d]===k+1?0:k+1;r()})},sent:{name:"Sentence starters",std:["W.4.1","W.4.2","W.4.3"],html:sentHtml}};const SUP_CAVEATS=[{t:"pv",std:["4.NBT.A.1"],msg:"The place value chart names the places, so count question 1 (what each 5 is worth) as supported."},{t:"pv",std:["4.NBT.A.3"],msg:"The place value chart shows which digit sits in each place. Rate on whether the student can decide to round up or down."},{t:"frac",msg:"Fraction strips can show the answer. Rate on whether the student can explain what the strips show."},{t:"mult",std:["4.NF.A.1","4.NF.A.2"],msg:"The multiplication chart supplies the facts. This stop still shows whether the student knows to multiply the top and bottom by the same number."},{t:"sent",msg:"Sentence starters supply the linking words and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"pv",std:["4.NF.C.6","4.NF.C.7"],msg:"The place value chart lines the digits up by place, which is most of what comparing decimals asks for. Count those checks as supported."},{t:"mult",std:["4.MD.A.1","4.MD.A.3"],msg:"The multiplication chart supplies the product. Rate these on choosing the right operation and the right unit, not on the fact itself."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
